CREATE TABLE account (
  id CHAR(36) NOT NULL DEFAULT (UUID()),
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
  deleted_at DATETIME(6),
  email VARCHAR(255) NOT NULL,
  balance DECIMAL(10, 2) NOT NULL,
  score DOUBLE,
  avatar LONGBLOB,
  payload JSON,
  labels JSON NOT NULL, -- an array stored as JSON
  ttl BIGINT, -- duration in microseconds
  ip VARCHAR(45),
  homepage_url VARCHAR(255),
  born DATE,
  alarm TIME(6),
  status ENUM('draft', 'live') NOT NULL DEFAULT 'draft',
  note LONGTEXT NOT NULL DEFAULT ('it''s; fine'),
  CONSTRAINT account_pkey PRIMARY KEY (id),
  CONSTRAINT account_email_key UNIQUE (email)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE INDEX account_deleted_at_idx ON account (deleted_at);
CREATE INDEX account_email_status_idx ON account (email, status);

